          "@type": "Question",
          "name": "How do I report PDUs to PMI?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Log into pmi.org, go to your certification dashboard, and click 'Report PDUs.' Select 'Education' as the category, enter the course name, dates, and number of hours."
