        {
          "@type": "Question",
          "name": "Do I need to take the full course or can I take part of it?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "You earn PDUs for the hours you complete. If a course is 8 hours, you earn 8 PDUs. PMI tracks by contact hours, not by course completion percentage."
          }
        },
        {
          "@type": "Question",
          "name": "What are the eligibility requirements to enroll in a PMP PDU course?",
          "acceptedAnswer": {
