    {
      "@type": "FAQPage",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "What are the eligibility requirements for the PMP?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "PMI requires: (1) a four-year degree plus 36 months of documented project management experience, OR a high school diploma plus 60 months of PM experience; and (2) 35 hours of formal PM education. Our PMP certification training and PMP bootcamp both satisfy the 35-hour requirement."
          }
        },
        {
          "@type": "Question",
          "name": "How long does it take to get PMP certified?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "With our live-virtual training, most students submit their PMI application on the final day of class. PMI approves applications in 5–10 business days. After approval, students schedule with Pearson VUE and typically sit the exam within 30–45 days of completing training."
          }
        },
        {
          "@type": "Question",
          "name": "What is the difference between PMP Certification Training and the PMP Bootcamp?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Both are 4-day live-virtual courses that satisfy PMI's 35-hour requirement. The PMP Certification Training ($1,995) follows a standard daily schedule (9am–5pm). The PMP Bootcamp ($2,495) is a more intensive format (9am–6pm) with additional exam simulation time and is structured specifically for students who want the fastest possible path to exam readiness. Both are covered by our Pass Guarantee."
          }
        },
        {
          "@type": "Question",
          "name": "What is your Pass Guarantee?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "If you complete our course, follow our post-course study plan, and don't pass the PMP exam on your first attempt, we enroll you in the next available session at no cost. No fine print beyond those two conditions."
          }
        },
        {
          "@type": "Question",
          "name": "How many questions are on the PMP exam?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "The PMP exam has 180 questions and a 4-hour time limit. Approximately half the questions are scenario-based, testing how you apply PMI's framework rather than testing memorization. Our training includes full 180-question timed mock exams."
          }
        },
        {
          "@type": "Question",
          "name": "What is the PMP exam fee?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "PMI charges $405 for members and $555 for non-members. PMI membership costs $139/year and includes a free digital copy of the PMBOK Guide, making membership the better financial choice for most candidates. The exam fee is paid directly to PMI and is separate from our training cost."
          }
        },
        {
          "@type": "Question",
          "name": "Is the PMP exam available online?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. The PMP is available as an online proctored exam through Pearson VUE — you can take it from home or at a Pearson VUE test center. Both options are identical in content and scoring."
          }
        },
        {
          "@type": "Question",
          "name": "How current is the PMP exam content?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "PMI updates the PMP Exam Content Outline periodically. The current version (effective 2021, with ongoing updates) requires approximately 50% agile and hybrid content — a significant shift from earlier versions. Our curriculum is fully updated to reflect the current outline, including the 2026 weighting."
          }
        },
        {
          "@type": "Question",
          "name": "What are the CAPM eligibility requirements?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "PMI requires a secondary school diploma (high school diploma or equivalent) and 23 hours of formal PM education. There is no work experience requirement. Our 3-day CAPM training satisfies the 23-hour requirement entirely."
          }
        },
        {
          "@type": "Question",
          "name": "What is the difference between the CAPM and the PMP?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "The PMP is the senior professional credential and requires 36 months of documented PM experience. The CAPM is the entry-level credential with no experience requirement. CAPM training hours count toward the PMP's 35-hour requirement, making the CAPM a structured pathway to the PMP for professionals who aren't yet experience-eligible."
          }
        },
        {
          "@type": "Question",
          "name": "Is the CAPM worth it in 2026?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes, particularly for professionals who don't yet have the experience for the PMP. The CAPM is recognized globally by employers as evidence of formal PM knowledge. It frequently differentiates candidates for coordinator, analyst, and associate PM roles — especially those competing against candidates without any PMI credential."
          }
        },
        {
          "@type": "Question",
          "name": "What is the difference between CAPM Certification Training and the CAPM Bootcamp?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Both are 3-day live-virtual courses that satisfy PMI's 23-hour requirement. The CAPM Certification Training ($795) runs at a standard pace (9am–5pm). The CAPM Bootcamp ($995) is a more intensive format (9am–6pm) designed for students who want maximum exam preparation in the shortest time. Both include our Pass Guarantee."
          }
